<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Personal Expense Tracker</title>
<style>
  * { box-sizing: border-box; }
  body {
    font-family: Arial, Helvetica, sans-serif;
    margin: 0;
    padding: 24px;
    background: #f4f5f7;
    color: #222;
  }
  h1 { font-size: 22px; margin: 0 0 16px; }
  .card {
    background: #fff;
    border: 1px solid #ddd;
    border-radius: 8px;
    padding: 16px;
    margin-bottom: 16px;
  }
  #expense-form {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    align-items: center;
  }
  #expense-form input,
  #expense-form select,
  #filters input,
  #filters select {
    padding: 8px;
    border: 1px solid #bbb;
    border-radius: 4px;
    font-size: 14px;
  }
  #amount { width: 110px; }
  #note { flex: 1; min-width: 140px; }
  #add-expense {
    padding: 8px 16px;
    background: #2f6fed;
    color: #fff;
    border: none;
    border-radius: 4px;
    font-size: 14px;
    cursor: pointer;
  }
  #add-expense:hover { background: #255bcc; }
  #form-error {
    color: #c0392b;
    font-size: 13px;
    margin-top: 8px;
    min-height: 16px;
  }
  #filters {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    align-items: center;
  }
  #filters label { font-size: 13px; color: #555; }
  #summary { font-size: 14px; }
  #summary .total-line { font-size: 16px; font-weight: bold; margin-bottom: 8px; }
  #cat-summary {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
  }
  .cat-total {
    background: #eef2fb;
    border: 1px solid #cdd9f2;
    border-radius: 4px;
    padding: 4px 10px;
    font-size: 13px;
  }
  .expense {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 10px 12px;
    border-bottom: 1px solid #e5e5e5;
    background: #fff;
  }
  .expense:first-child { border-top-left-radius: 8px; border-top-right-radius: 8px; }
  .expense:last-child { border-bottom: none; border-bottom-left-radius: 8px; border-bottom-right-radius: 8px; }
  .exp-amount { font-weight: bold; width: 90px; }
  .exp-cat {
    text-transform: capitalize;
    background: #e8f0e8;
    border-radius: 4px;
    padding: 2px 8px;
    font-size: 12px;
  }
  .exp-date { color: #666; font-size: 13px; width: 100px; }
  .exp-note { color: #555; font-size: 13px; flex: 1; }
  .exp-del {
    background: none;
    border: 1px solid #c0392b;
    color: #c0392b;
    border-radius: 4px;
    padding: 4px 10px;
    font-size: 12px;
    cursor: pointer;
  }
  .exp-del:hover { background: #c0392b; color: #fff; }
  #empty-msg { color: #777; font-size: 14px; padding: 8px 2px; }
</style>
</head>
<body>

<h1>Personal Expense Tracker</h1>

<div class="card">
  <form id="expense-form" novalidate>
    <input type="number" id="amount" step="0.01" min="0" placeholder="Amount" aria-label="Amount">
    <select id="category" aria-label="Category">
      <option value="groceries">groceries</option>
      <option value="transport">transport</option>
      <option value="bills">bills</option>
      <option value="fun">fun</option>
    </select>
    <input type="date" id="date" aria-label="Date">
    <input type="text" id="note" placeholder="Note (optional)" aria-label="Note">
    <button type="submit" id="add-expense">Add Expense</button>
  </form>
  <div id="form-error"></div>
</div>

<div class="card" id="filters">
  <label for="filter-category">Category</label>
  <select id="filter-category">
    <option value="all">all</option>
    <option value="groceries">groceries</option>
    <option value="transport">transport</option>
    <option value="bills">bills</option>
    <option value="fun">fun</option>
  </select>
  <label for="filter-from">From</label>
  <input type="date" id="filter-from">
  <label for="filter-to">To</label>
  <input type="date" id="filter-to">
  <button type="button" id="clear-filters">Clear filters</button>
</div>

<div class="card" id="summary">
  <div class="total-line">Total (visible): $<span id="total">0.00</span></div>
  <div id="cat-summary">
    <span class="cat-total" data-cat="groceries">groceries: 0.00</span>
    <span class="cat-total" data-cat="transport">transport: 0.00</span>
    <span class="cat-total" data-cat="bills">bills: 0.00</span>
    <span class="cat-total" data-cat="fun">fun: 0.00</span>
  </div>
</div>

<div id="expenses"></div>
<div id="empty-msg" style="display:none;">No expenses to show.</div>

<script>
(function () {
  'use strict';

  var CATEGORIES = ['groceries', 'transport', 'bills', 'fun'];
  var STORAGE_KEY = 'expenses';

  var amountEl = document.getElementById('amount');
  var categoryEl = document.getElementById('category');
  var dateEl = document.getElementById('date');
  var noteEl = document.getElementById('note');
  var formEl = document.getElementById('expense-form');
  var errorEl = document.getElementById('form-error');
  var filterCatEl = document.getElementById('filter-category');
  var filterFromEl = document.getElementById('filter-from');
  var filterToEl = document.getElementById('filter-to');
  var clearFiltersBtn = document.getElementById('clear-filters');
  var totalEl = document.getElementById('total');
  var listEl = document.getElementById('expenses');
  var emptyMsg = document.getElementById('empty-msg');

  var expenses = load();

  function load() {
    try {
      var raw = localStorage.getItem(STORAGE_KEY);
      var data = raw ? JSON.parse(raw) : [];
      return Array.isArray(data) ? data : [];
    } catch (e) {
      return [];
    }
  }

  function save() {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(expenses));
  }

  function makeId() {
    return Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 9);
  }

  function formatMoney(n) {
    return n.toFixed(2);
  }

  function getVisible() {
    var cat = filterCatEl.value;
    var from = filterFromEl.value; // 'YYYY-MM-DD' or ''
    var to = filterToEl.value;
    return expenses.filter(function (e) {
      if (cat !== 'all' && e.category !== cat) return false;
      if (from && e.date < from) return false;
      if (to && e.date > to) return false;
      return true;
    });
  }

  function render() {
    var visible = getVisible();

    // Render rows (expenses array is kept newest-first).
    listEl.innerHTML = '';
    visible.forEach(function (e) {
      var row = document.createElement('div');
      row.className = 'expense';
      row.setAttribute('data-id', e.id);
      row.setAttribute('data-cat', e.category);

      var amt = document.createElement('span');
      amt.className = 'exp-amount';
      amt.textContent = '$' + formatMoney(e.amount);

      var cat = document.createElement('span');
      cat.className = 'exp-cat';
      cat.textContent = e.category;

      var dt = document.createElement('span');
      dt.className = 'exp-date';
      dt.textContent = e.date;

      var note = document.createElement('span');
      note.className = 'exp-note';
      note.textContent = e.note || '';

      var del = document.createElement('button');
      del.type = 'button';
      del.className = 'exp-del';
      del.textContent = 'Delete';
      del.addEventListener('click', function () {
        deleteExpense(e.id);
      });

      row.appendChild(amt);
      row.appendChild(cat);
      row.appendChild(dt);
      row.appendChild(note);
      row.appendChild(del);
      listEl.appendChild(row);
    });

    emptyMsg.style.display = visible.length === 0 ? 'block' : 'none';

    // Totals over visible expenses.
    var sum = 0;
    var perCat = {};
    CATEGORIES.forEach(function (c) { perCat[c] = 0; });
    visible.forEach(function (e) {
      sum += e.amount;
      if (perCat.hasOwnProperty(e.category)) perCat[e.category] += e.amount;
    });
    totalEl.textContent = formatMoney(sum);

    var catEls = document.querySelectorAll('.cat-total');
    for (var i = 0; i < catEls.length; i++) {
      var c = catEls[i].getAttribute('data-cat');
      catEls[i].textContent = c + ': ' + formatMoney(perCat[c] || 0);
    }
  }

  function deleteExpense(id) {
    for (var i = 0; i < expenses.length; i++) {
      if (expenses[i].id === id) {
        expenses.splice(i, 1);
        break;
      }
    }
    save();
    render();
  }

  formEl.addEventListener('submit', function (ev) {
    ev.preventDefault();

    var rawAmount = amountEl.value.trim();
    var amount = parseFloat(rawAmount);
    var date = dateEl.value;

    if (rawAmount === '' || isNaN(amount) || amount <= 0) {
      errorEl.textContent = 'Please enter a valid amount greater than zero.';
      return;
    }
    if (!date) {
      errorEl.textContent = 'Please select a date.';
      return;
    }

    var expense = {
      id: makeId(),
      amount: amount,
      category: categoryEl.value,
      date: date,
      note: noteEl.value.trim()
    };

    // Newest first.
    expenses.unshift(expense);
    save();

    errorEl.textContent = '';
    amountEl.value = '';
    noteEl.value = '';
    amountEl.focus();

    render();
  });

  filterCatEl.addEventListener('change', render);
  filterFromEl.addEventListener('change', render);
  filterFromEl.addEventListener('input', render);
  filterToEl.addEventListener('change', render);
  filterToEl.addEventListener('input', render);

  clearFiltersBtn.addEventListener('click', function () {
    filterCatEl.value = 'all';
    filterFromEl.value = '';
    filterToEl.value = '';
    render();
  });

  render();
})();
</script>

</body>
</html>
